for(const [id,key]of [['field-toggle','field'],['grid-toggle','grid'],['paths-toggle','paths']])$(id).onchange=e=>{state[key]=e.target.checked;draw();};
$('zoom-in').onclick=()=>zoom(.8);$('zoom-out').onclick=()=>zoom(1.25);$('reset-view').onclick=()=>{state.range=5;state.yaw=.65;state.pitch=.5;drawPhase();};$('play').onclick=play;$('restart').onclick=()=>{resetTime();draw();};$('timeline').oninput=e=>{pause();state.t=Number(e.target.value);draw();};$('speed').onchange=e=>{state.speed=Number(e.target.value);};
$('duration').onchange=e=>{const v=Number(e.target.value);if(!Number.isFinite(v)||v<1||v>30){e.target.value=state.T;return;}resetTime();state.T=v;$('timeline').max=v;rebuild();};$('chart-trajectory').onchange=e=>{state.selected=Number(e.target.value);drawChart();};
